package org.fribok.bookkeeping.dataformat;
import org.junit.jupiter.api.Test;import java.sql.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class NormalizedPeriodicInvoiceSchemaTest{
 @Test void createsCompletePeriodicInvoiceGraph()throws Exception{try(Connection c=conn()){new SchemaMigrationRunner(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC)).migrate(c,NormalizedSchemaMigrations.load());long company=company(c);try(var p=c.prepareStatement("INSERT INTO periodic_invoice (legacy_id,company_id,number,start_date,count,period_months,description,period_start,period_end,append_period,append_information,template_tax_free,template_eu_sale_commodity,template_eu_sale_third_party_commodity,template_printed,template_entered,template_reminder_count,template_interest_invoiced,template_stock_influencing) VALUES (?,?,?,?,?,?,?,?,?,?,?,FALSE,FALSE,FALSE,FALSE,FALSE,0,FALSE,FALSE)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,1);p.setLong(2,company);p.setInt(3,7);p.setObject(4,LocalDate.of(2026,1,1));p.setInt(5,3);p.setInt(6,1);p.setString(7,"");p.setObject(8,LocalDate.of(2026,1,1));p.setObject(9,LocalDate.of(2026,1,31));p.setBoolean(10,true);p.setBoolean(11,true);p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();long id=k.getLong(1);try(var t=c.prepareStatement("INSERT INTO periodic_invoice_template_row VALUES (?,?,?,?,?,?,?,?,?,?,?,?)")){t.setLong(1,id);t.setInt(2,0);t.setString(3,null);t.setString(4,"");t.setBigDecimal(5,new java.math.BigDecimal("10.00"));t.setBigDecimal(6,new java.math.BigDecimal("1"));t.setString(7,null);t.setBigDecimal(8,null);t.setString(9,null);t.setNull(10,Types.INTEGER);t.setString(11,null);t.setString(12,null);t.executeUpdate();}try(var i=c.prepareStatement("INSERT INTO periodic_invoice_instance (periodic_invoice_id,row_number,tax_free,eu_sale_commodity,eu_sale_third_party_commodity,printed,entered,reminder_count,interest_invoiced,stock_influencing,added) VALUES (?,0,FALSE,FALSE,FALSE,FALSE,FALSE,0,FALSE,FALSE,TRUE)")){i.setLong(1,id);i.executeUpdate();}try(var i=c.prepareStatement("INSERT INTO periodic_invoice_instance_row VALUES (?,0,0,NULL,'',10,1,NULL,NULL,NULL,NULL,NULL,NULL)")){i.setLong(1,id);i.executeUpdate();}}}c.commit();assertThat(count(c,"periodic_invoice")).isEqualTo(1);assertThat(count(c,"periodic_invoice_instance")).isEqualTo(1);assertThat(count(c,"periodic_invoice_instance_row")).isEqualTo(1);}}
 private static Connection conn()throws Exception{Class.forName("org.hsqldb.jdbcDriver");Connection c=DriverManager.getConnection("jdbc:hsqldb:mem:periodic_schema_"+UUID.randomUUID(),"sa","");c.setAutoCommit(false);return c;}private static long company(Connection c)throws Exception{try(var p=c.prepareStatement("INSERT INTO company (legacy_id) VALUES (1)",Statement.RETURN_GENERATED_KEYS)){p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}private static long count(Connection c,String t)throws Exception{try(var s=c.createStatement();var r=s.executeQuery("SELECT COUNT(*) FROM "+t)){r.next();return r.getLong(1);}}
}
